                    role="listitem"
                    className={cn(
                      "w-[50px] h-[50px] rounded-full border-[2.5px] border-[#9AF500] overflow-hidden bg-[#E5E5E5] dark:bg-[#E5E5E5] shrink-0",
                      index > 0 && "-ml-[10px]"
                    )}
                  >
                    <img
                      src={trainer.avatarUrl}
                      alt={trainer.name}
                      loading="lazy"
                      decoding="async"
                      className="w-full h-full object-cover grayscale"
                    />
                  </div>
                ))}
              </div>
            </section>
          </div>
        </div>
      </div>
    </div>
  );
};

